import re

_PATTERN = re.compile(
    r" *(?:([0-9]+)d)? *(?:([0-9]+)h)? *(?:([0-9]+)m)? *(?:([0-9]+)s)? *"
)
_FACTORS = (86400, 3600, 60, 1)


def parse_duration(text):
    match = _PATTERN.fullmatch(text)
    if match is None or all(g is None for g in match.groups()):
        raise ValueError("invalid duration: %r" % text)
    return sum(
        int(g) * f for g, f in zip(match.groups(), _FACTORS) if g is not None
    )

